create table if not exists public.plano_itens(id int primary key, semana date not null, materia text not null, frente text, assunto text not null, obs text);
create table if not exists public.plano_feito(email text not null, item int not null references public.plano_itens(id) on delete cascade, feito_em timestamptz not null default now(), primary key(email,item));
alter table public.plano_itens enable row level security; alter table public.plano_feito enable row level security;
drop policy if exists plano_itens_ler on public.plano_itens; drop policy if exists plano_itens_admin on public.plano_itens;
drop policy if exists plano_feito_ler on public.plano_feito; drop policy if exists plano_feito_ins on public.plano_feito; drop policy if exists plano_feito_del on public.plano_feito;
create policy plano_itens_ler on public.plano_itens for select to authenticated using (public.is_assessoria());
create policy plano_itens_admin on public.plano_itens for all to authenticated using (public.is_admin()) with check (public.is_admin());
create policy plano_feito_ler on public.plano_feito for select to authenticated using (public.is_admin() or email=lower(coalesce(auth.jwt()->>'email','')));
create policy plano_feito_ins on public.plano_feito for insert to authenticated with check (public.is_admin() or (public.is_assessoria() and email=lower(coalesce(auth.jwt()->>'email',''))));
create policy plano_feito_del on public.plano_feito for delete to authenticated using (public.is_admin() or email=lower(coalesce(auth.jwt()->>'email','')));
grant select,insert,update,delete on public.plano_itens, public.plano_feito to authenticated;
